test('invoiceTotals: VAT never goes below zero', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 100, vatRate: 21, discountPercent: 100 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert(result.vat >= 0);
});

test('lineDiscount: bulk discount with 10 units', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const total = 10 * 1000;
  const bulkDiscount = Math.round(total * 0.025);
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount: bulk discount with 11 units', () => {
  const line = { qty: 11, unitPrice: 1000, vatRate: 21 };
  const total = 11 * 1000;
  const bulkDiscount = Math.round(total * 0.025);
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount: no bulk discount with 9 units', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount: bulk discount with primary discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const total = 10 * 1000;
  const primaryDiscount = Math.round(total * 0.1);
  const amountAfterPrimary = total - primaryDiscount;
  const bulkDiscount = Math.round(amountAfterPrimary * 0.025);
  const expectedTotal = primaryDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expectedTotal);
});

test('lineDiscount: bulk discount applied after primary discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 20 };
  const total = 100000;
  const primaryDiscount = Math.round(total * 0.2);
  const amountAfterPrimary = total - primaryDiscount;
  const bulkDiscount = Math.round(amountAfterPrimary * 0.025);
  assert.equal(lineDiscount(line), primaryDiscount + bulkDiscount);
});

test('lineDiscount: bulk discount is 2.5%', () => {
  const line = { qty: 100, unitPrice: 10000, vatRate: 21 };
  const total = 1000000;
  const expectedBulk = Math.round(total * 0.025);
  assert.equal(lineDiscount(line), expectedBulk);
});

test('lineVAT: VAT calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const total = 10000;
  const bulkDiscount = Math.round(total * 0.025);
  const amountAfterDiscount = total - bulkDiscount;
  const expectedVAT = Math.round(amountAfterDiscount * 0.21);
  assert.equal(lineVAT(line), expectedVAT);
});

test('lineVAT: with both primary and bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const total = 10000;
  const primaryDiscount = Math.round(total * 0.1);
  const amountAfterPrimary = total - primaryDiscount;
  const bulkDiscount = Math.round(amountAfterPrimary * 0.025);
  const amountAfterAll = amountAfterPrimary - bulkDiscount;
  const expectedVAT = Math.round(amountAfterAll * 0.21);
  assert.equal(lineVAT(line), expectedVAT);
});

test('invoiceTotals: bulk discount counted in discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert(result.discount > 0);
  const total = 10000;
  const expectedDiscount = Math.round(total * 0.025);
  assert.equal(result.discount, expectedDiscount);
});

test('invoiceTotals: multiple lines, some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  const line1Total = 10000;
  const line1Discount = Math.round(line1Total * 0.025);
  assert(result.discount >= line1Discount);
});

test('invoiceTotals: bulk discount + primary discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const result = invoiceTotals(invoice);
  const total = 10000;
  const primary = Math.round(total * 0.1);
  const afterPrimary = total - primary;
  const bulk = Math.round(afterPrimary * 0.025);
  assert.equal(result.discount, primary + bulk);
});

test('lineDiscount: large quantity with bulk discount', () => {
  const line = { qty: 1000, unitPrice: 9500, vatRate: 21 };
  const total = 9500000;
  const bulkDiscount = Math.round(total * 0.025);
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount: boundary case exactly 10 units', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 21 };
  assert(lineDiscount(line) > 0);
});

test('lineDiscount: boundary case exactly 9 units', () => {
  const line = { qty: 9, unitPrice: 100, vatRate: 21 };
  assert.equal(lineDiscount(line), 0);
});

test('invoiceTotals: invoice with 10+ unit lines and discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 5 },
      { qty: 20, unitPrice: 500, vatRate: 21 },
      { qty: 8, unitPrice: 2000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert(result.discount > 0);
  assert(result.vat > 0);
  assert(result.total > 0);
});

test('lineDiscount: with 100% primary discount still has 0 bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 100 };
  const total = 10000;
  const primaryDiscount = total;
  const amountAfterPrimary = 0;
  const bulkDiscount = 0;
  assert.equal(lineDiscount(line), primaryDiscount + bulkDiscount);
});

test('lineVAT: bulk discount reduces VAT base', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);
  assert(discount > 0);
  const total = 10000;
  const vatBase = total - discount;
  const expectedVAT = Math.round(vatBase * 0.21);
  assert.equal(lineVAT(line), expectedVAT);
});

