  assert(!text.includes('Subtotal:'));
  assert(!text.includes('Discount:'));
});

test('renderInvoiceText: with line discount shows subtotal and discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // 5 x 95 = 475, 10% discount = 47.50
  // VAT on 427.50 at 21% = 89.78
  // Total: 517.28
  assert(text.includes('Subtotal: €475.00'));
  assert(text.includes('Discount: -€47.50'));
  assert(text.includes('VAT: €89.78'));
  assert(text.includes('Total: €517.28'));
});

test('renderInvoiceText: with multiple lines and discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
