  // 5 x 95 = 475, VAT 21% = 99.75
  // Total: 574.75
  assert(text.includes('VAT: €99.75'));
  assert(text.includes('Total: €574.75'));
});

test('renderInvoiceText: with VAT (9%)', () => {
