test('renderInvoiceText: multiple lines with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // 475, VAT 21% = 99.75
      { sku: 'PRINT-A4', qty: 100 }, // 37, VAT 9% = 3.33
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 600, VAT 0% = 0
    ],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // Standard tier with no discount, so no subtotal line
  // VAT: 103.08 (99.75 + 3.33 + 0)
  // Total: 1215.08
  assert(text.includes('VAT: €103.08'));
  assert(text.includes('Total: €1,215.08'));
  assert(!text.includes('Subtotal:'));
});

