  const result = overdueInvoices([invIssue.value], '2026-10-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 20);
});

test('overdueInvoices: with voucher applied', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert(inv.ok);

  const invWithVoucher = { ...inv.value, voucher: { code: 'SAVE10', amount: 10000 } };
  const invIssue = issueInvoice(invWithVoucher, []);
  assert(invIssue.ok);

  const result = overdueInvoices([invIssue.value], '2026-10-20');

  assert.equal(result.length, 1);
  assert(result[0].due > 0);
});

test('overdueInvoices: daysOverdue is exact', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert(inv.ok);

