      { sku: 'WORKSHOP-DAY', qty: 1 }, // 60000, VAT 0% = 0
    ],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // VAT: 9975 + 325 + 0 = 10300 cents = €103.00
