test('createInvoice: line discountPercent overrides tier discount', () => {
  // C-001 is gold (5%), but line specifies 10%
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert(result.ok);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice: line discountPercent of 0 overrides tier discount', () => {
  // C-001 is gold (5%), but line explicitly sets 0%
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 0 }],
  });

  assert(result.ok);
  // Explicit 0% should not set discountPercent at all
  assert.equal(result.value.lines[0].discountPercent, undefined);
});

test('createInvoice: multiple lines get tier discount applied to all', () => {
  // C-003 is silver (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert(result.ok);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 2.5);
});

test('createInvoice: mixed tier and explicit discounts', () => {
  // C-001 is gold (5%)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // gets gold tier 5%
      { sku: 'DES-HOUR', qty: 3, discountPercent: 10 }, // explicit 10%
      { sku: 'COPY-HOUR', qty: 2, discountPercent: 0 }, // explicit 0%
    ],
  });

  assert(result.ok);
  assert.equal(result.value.lines[0].discountPercent, 5);
  assert.equal(result.value.lines[1].discountPercent, 10);
  assert.equal(result.value.lines[2].discountPercent, undefined);
});

test('invoiceTotals: includes tier discount in calculation', () => {
  // C-001 is gold (5%)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  // 5 x 9500 = 47500, 5% discount = 2375
  // VAT on 45125 at 21% = 9476.25 -> 9476
  // Total: 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

test('invoiceTotals: tier and explicit discounts combined', () => {
  // C-003 is silver (2.5%)
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // 5 x 9500 = 47500, 2.5% = 1188
      { sku: 'DES-HOUR', qty: 3, discountPercent: 10 }, // 3 x 8500 = 25500, 10% = 2550
    ],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  // Subtotal: 47500 + 25500 = 73000
  // Discount: 1188 + 2550 = 3738
  // VAT: (47500-1188)*21% + (25500-2550)*21% = 46312*21% + 22950*21% = 9726 + 4820 = 14546
  // Total: 73000 - 3738 + 14546 = 83808
  assert.equal(totals.subtotal, 73000);
  assert.equal(totals.discount, 3738);
  assert.equal(totals.vat, 14546);
  assert.equal(totals.total, 83808);
});

test('lineVAT: calculates VAT on line total', () => {
  // 5 x 9500 = 47500, 21% VAT = 9975
  const vat = lineVAT({ qty: 5, unitPrice: 9500, vatRate: 21 });
  assert.equal(vat, 9975);
});

test('lineVAT: with 9% VAT rate', () => {
  // 100 x 37 = 3700, bulk discount 2.5% = 92, amount after = 3608, 9% VAT = 325
  const vat = lineVAT({ qty: 100, unitPrice: 37, vatRate: 9 });
  assert.equal(vat, 325);
});

test('lineVAT: with 0% VAT rate', () => {
  const vat = lineVAT({ qty: 5, unitPrice: 9500, vatRate: 0 });
  assert.equal(vat, 0);
});

test('lineVAT: VAT is calculated on amount after discount', () => {
  // 5 x 9500 = 47500, 10% discount = 4750
  // After discount: 42750, 21% VAT = 8977.5 -> 8978
  const vat = lineVAT({ qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 10 });
  assert.equal(vat, 8978);
});

test('lineVAT: with 100% discount, VAT is zero', () => {
  const vat = lineVAT({ qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 100 });
  assert.equal(vat, 0);
});

test('invoiceTotals: includes VAT in total calculation', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 47500, VAT: 9975
  // Total: 57475
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.vat, 9975);
  assert.equal(totals.total, 57475);
});

test('invoiceTotals: with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 10 }],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 47500
  // Discount: 4750
  // VAT on (47500 - 4750) = 21% of 42750 = 8977.5 -> 8978
  // Total: 47500 - 4750 + 8978 = 51728
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 8978);
  assert.equal(totals.total, 51728);
});

test('invoiceTotals: multiple lines with different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, vatRate: 21 }, // 47500, VAT: 9975
      { qty: 100, unitPrice: 37, vatRate: 9 }, // 3700, bulk discount 92, VAT: 325
      { qty: 1, unitPrice: 60000, vatRate: 0 }, // 60000, VAT: 0
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 47500 + 3700 + 60000 = 111200
  // Discount: 92 (bulk on line 2)
  // VAT: 9975 + 325 + 0 = 10300
  // Total: 111200 - 92 + 10300 = 121408
  assert.equal(totals.subtotal, 111200);
  assert.equal(totals.discount, 92);
  assert.equal(totals.vat, 10300);
  assert.equal(totals.total, 121408);
});

test('invoiceTotals: with tier discount and VAT', () => {
  // C-001 is gold (5% discount), DEV-HOUR has 21% VAT
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  // Subtotal: 47500
  // Discount: 5% = 2375
  // VAT on 45125 at 21% = 9476.25 -> 9476
  // Total: 47500 - 2375 + 9476 = 54601
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 2375);
  assert.equal(totals.vat, 9476);
  assert.equal(totals.total, 54601);
});

test('invoiceTotals: VAT never goes below zero', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 100, Discount: 100, so amount for VAT = 0
  // VAT: 0, Total: 0
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

