    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const voucherResult = applyVoucher(result.value, { code: 'SAVE10', amount: 10000 });

  assert(voucherResult.ok);
  assert.equal(voucherResult.value.voucher.code, 'SAVE10');
  assert.equal(voucherResult.value.voucher.amount, 10000);
});

test('applyVoucher: reduces total in invoiceTotals', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const totalsWithout = invoiceTotals(result.value);

  const voucherResult = applyVoucher(result.value, { code: 'SAVE10', amount: 10000 });
  assert(voucherResult.ok);
  const totalsWith = invoiceTotals(voucherResult.value);

  assert.equal(totalsWith.voucher, 10000);
  assert.equal(totalsWith.total, totalsWithout.total - 10000);
});

test('applyVoucher: rejects non-draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const issueResult = issueInvoice(result.value, []);
  assert(issueResult.ok);

  const voucherResult = applyVoucher(issueResult.value, { code: 'SAVE10', amount: 10000 });

  assert(!voucherResult.ok);
  assert.equal(voucherResult.error, 'NOT_DRAFT');
});

test('applyVoucher: rejects duplicate voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const voucher1 = applyVoucher(result.value, { code: 'SAVE10', amount: 10000 });
  assert(voucher1.ok);

  const voucher2 = applyVoucher(voucher1.value, { code: 'SAVE20', amount: 5000 });

  assert(!voucher2.ok);
  assert.equal(voucher2.error, 'VOUCHER_EXISTS');
});

