test('applyVoucher: does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const originalInvoice = JSON.parse(JSON.stringify(result.value));

  applyVoucher(result.value, { code: 'SAVE10', amount: 10000 });

  assert.deepEqual(result.value, originalInvoice);
});

test('invoiceTotals: includes voucher in calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const voucherResult = applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });
  assert(voucherResult.ok);

  const totals = invoiceTotals(voucherResult.value);
  // 5 x 95 = 475, VAT 21% = 99.75, Total: 574.75 - 50 = 524.75
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 57475 - 5000);
});

