test('invoiceTotals: total never goes below zero with voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert(result.ok);
  const voucherResult = applyVoucher(result.value, { code: 'FREE', amount: 1000000 });
  assert(voucherResult.ok);

  const totals = invoiceTotals(voucherResult.value);
  assert.equal(totals.total, 0);
  assert(totals.total >= 0);
});

